// Protected paths within the repository that meta-edit must never let an
// edit_* tool modify. Edits to these paths are rejected during validation.
//
// The MVP protects only the meta-edit state and tmp directories. Hooks
// (deny-bash-write-bypass) extend best-effort coverage to shell-level
// writes, but the server's own gate is here.

import * as fs from "node:fs";
import * as path from "node:path";

import { realpathOfDeepestExisting } from "../utils/realpath.js";

export const PROTECTED_PREFIXES: readonly string[] = [
  ".meta-edit/state/",
  ".meta-edit/tmp/",
];

export interface IsProtectedPathOptions {
  /**
   * Absolute path to the repository root. When supplied, isProtectedPath
   * resolves the input via fs.realpathSync so that symlinks pointing into
   * a protected directory are caught (issue 015 / a4-01). When omitted, or
   * when the path does not exist on disk, falls back to a pure lexical check.
   */
  repoRoot?: string;
}

/**
 * Normalize a repo-relative path string for the prefix-based protected-path
 * check.
 *
 * Contract (Codex round-1 a4-02):
 *   - Strips a leading "./", leading slashes, and collapses "//" to "/".
 *   - Replaces backslashes with forward slashes so Windows-style spellings
 *     hit the same prefixes.
 *   - **Throws** when the input contains a NUL byte ("\0"). NUL is never a
 *     legitimate path character; allowing it through would let a caller
 *     defeat the startsWith check (e.g. ".meta-edit\0/state/..." does not
 *     start with ".meta-edit/" but the kernel still reads the path up to
 *     the NUL on most syscalls).
 *
 * Callers must either catch the throw or be in a context where propagation
 * is acceptable. Existing call sites:
 *   - isProtectedPath()      catches and returns true (fail-closed).
 *   - common.ts ensureSafe() catches and returns a structured error.
 *   - common.ts (~line 447)  input is path.relative output, never NUL.
 *   - apply.ts (~line 131)   input is path.relative output, never NUL.
 */
export function normalizeRepoRelative(p: string): string {
  // Fail-closed on NUL bytes: a NUL is never legitimate in a path, and
  // silently passing it through allows callers to defeat the prefix check
  // (e.g. ".meta-edit�/state/..." does not start with ".meta-edit/").
  // See issue 016 (a4-02).
  if (p.includes("�")) {
    throw new Error("path contains NUL byte");
  }
  let n = p.replace(/\\/g, "/");
  while (n.startsWith("./")) {
    n = n.slice(2);
  }
  while (n.startsWith("/")) {
    n = n.slice(1);
  }
  return n.replace(/\/+/g, "/");
}

// Case-folding is only safe on filesystems whose default semantics are
// case-insensitive (default-config macOS, Windows). On case-sensitive
// filesystems (Linux, and case-sensitive APFS volumes) ".META-EDIT/state/foo"
// is a genuinely different filesystem path from ".meta-edit/state/foo", so
// folding the input would over-reach and reject paths the kernel would
// happily serve as distinct files. Codex round-1 a4-03 finding.
const CASE_INSENSITIVE_FS =
  process.platform === "darwin" || process.platform === "win32";

function matchesProtectedPrefix(norm: string): boolean {
  // Match against the literal form on every platform, and additionally
  // against a lowercased form on case-insensitive filesystems (default macOS
  // and Windows). The prefixes are already lowercase, so a startsWith check
  // on the folded form covers ".META-EDIT/STATE/..." aliases when the host
  // FS would treat them as identical to the canonical form.
  //
  // Additionally, match the exact directory name (the prefix minus its
  // trailing slash) so a caller passing the bare protected directory path
  // (e.g. ".meta-edit/state") is also rejected. See issue 017 (a4-03).
  const folded = CASE_INSENSITIVE_FS ? norm.toLowerCase() : null;
  return PROTECTED_PREFIXES.some((prefix) => {
    const dir = prefix.endsWith("/") ? prefix.slice(0, -1) : prefix;
    if (norm.startsWith(prefix) || norm === dir) {
      return true;
    }
    if (folded !== null && (folded.startsWith(prefix) || folded === dir)) {
      return true;
    }
    return false;
  });
}

export function isProtectedPath(
  p: string,
  options: IsProtectedPathOptions = {},
): boolean {
  // Fail-closed on NUL bytes (a4-02): if the input contains a NUL we cannot
  // tell what protected directory it is trying to reference, so we treat it
  // as protected. normalizeRepoRelative throws on NUL; we catch and return
  // true rather than propagate, so the guard remains a total function for
  // its callers (validation paths, hooks).
  let norm: string;
  try {
    norm = normalizeRepoRelative(p);
  } catch {
    return true;
  }

  // Lexical check first — catches literal protected-prefix paths regardless
  // of whether the filesystem state matches.
  if (matchesProtectedPrefix(norm)) {
    return true;
  }

  // Symlink-aware check (a4-01): when the caller supplies a repoRoot, attempt
  // to canonicalize the path via fs.realpathSync. If the resolved real path
  // lands inside a protected directory under the repo, return true. If the
  // path does not exist on disk (ENOENT/ENOTDIR) or realpath fails, we cannot
  // make a stronger claim than the lexical check above already made — so we
  // return false (the lexical check has already returned true above when it
  // would have).
  const repoRoot = options.repoRoot;
  if (repoRoot && !path.isAbsolute(p)) {
    try {
      const absInput = path.resolve(repoRoot, norm);
      // Use deepest-existing realpath: the leaf may be a not-yet-created
      // file ("link/state/edits.jsonl" before the write). We resolve every
      // existing component's symlinks, then re-attach the missing tail.
      const realResolved = realpathOfDeepestExisting(absInput);
      if (realResolved === null) {
        return false;
      }
      let realRoot: string;
      try {
        realRoot = fs.realpathSync(repoRoot);
      } catch {
        realRoot = path.resolve(repoRoot);
      }
      // Only honor symlink resolution that stays inside the repo. Out-of-repo
      // resolutions are a separate concern handled by the caller's traversal
      // check; here we only care about the protected-prefix question.
      if (
        realResolved === realRoot ||
        realResolved.startsWith(realRoot + path.sep)
      ) {
        const canonicalRel = normalizeRepoRelative(
          path.relative(realRoot, realResolved),
        );
        if (matchesProtectedPrefix(canonicalRel)) {
          return true;
        }
      }
    } catch {
      // EACCES / ELOOP / unexpected — fall through to lexical fallback.
    }
  }

  return false;
}
